#include <Arduino.h>
#include <DHT.h>
#include <TM1637Display.h>
#include <math.h>
DHT dht(7,DHT11);
TM1637Display display(4,5);
float tempValue=NAN, distanceValue=NAN;
unsigned long epoch, nextTemp, nextDistance, alarmEpoch, lastReport;
uint8_t previousMask=0;
bool sounding=false;
void reportReasons(uint8_t mask){
  if(mask&1) Serial.println("ALARM_TEMP");
  if(mask&2) Serial.println("ALARM_DISTANCE");
}
void setup(){
  Serial.begin(9600);
  pinMode(8,OUTPUT); digitalWrite(8,LOW);
  pinMode(9,INPUT); pinMode(6,OUTPUT);
  noTone(6); dht.begin(); display.setBrightness(7); display.clear();
  epoch=millis(); nextTemp=epoch; nextDistance=epoch;
}
void loop(){
  unsigned long now=millis();
  if((long)(now-nextTemp)>=0){
    nextTemp=now+2000;
    tempValue=dht.readTemperature();
  }
  now=millis();
  if((long)(now-nextDistance)>=0){
    nextDistance=now+100;
    digitalWrite(8,LOW); delayMicroseconds(2);
    digitalWrite(8,HIGH); delayMicroseconds(10); digitalWrite(8,LOW);
    unsigned long echo=pulseIn(9,HIGH,25000UL);
    float cm=echo/58.0f;
    distanceValue=(echo && cm>=2.0f && cm<=400.0f)?cm:NAN;
  }
  now=millis();
  uint8_t mask=0;
  if(!isnan(tempValue) && tempValue>32.0f) mask|=1;
  if(!isnan(distanceValue) && distanceValue<15.0f) mask|=2;
  if(mask && !previousMask) alarmEpoch=now;
  if(mask && (mask!=previousMask || now-lastReport>=1000UL)){
    reportReasons(mask); lastReport=now;
  }
  bool shouldSound=mask && ((now-alarmEpoch)%1000UL<500UL);
  if(shouldSound!=sounding){
    if(shouldSound) tone(6,1000); else noTone(6);
    sounding=shouldSound;
  }
  previousMask=mask;
  float selected=(((now-epoch)/2000UL)%2==0)?tempValue:distanceValue;
  if(isnan(selected)) display.clear();
  else display.showNumberDec((int)roundf(selected),false);
}
